// Configure your slaves here
const units = [1,2,3,4,5,6,7];

// Register request settings (your current reads)
const address = 0;
const quantity = 16;
const fc = 3; // 3 = Holding Registers

let idx = context.get('idx') || 0;
const unitid = units[idx];

// Advance index for next tick
idx = (idx + 1) % units.length;
context.set('idx', idx);

// Build modbus-flex-getter request
msg.payload = {
  fc,
  unitid,
  address,
  quantity
};

// Useful for routing/debug
msg.unitid = unitid;
msg.topic = `MBTCP unit ${unitid} HR ${address} qty ${quantity}`;

return msg;

// node-red-contrib-modbus returns a structured payload.
// Normalize to: msg.payload = registersArray, msg.unitid = unitid

const p = msg.payload || {};

// Try common locations for unitid
msg.unitid = msg.unitid || p.unitid || (p.request && p.request.unitid) || (p.modbusRequest && p.modbusRequest.unitid);

// Try common locations for data array
const regs = p.data || p.payload || p.register || p.responseBuffer;

if (Array.isArray(regs)) {
  msg.payload = regs;
  return msg;
}

// In some versions, data is at msg.payload.data
if (p.data && Array.isArray(p.data)) {
  msg.payload = p.data;
  return msg;
}

// If we can't find registers, pass whole thing to debug
return msg;

// --- Output 1: scaled value from index 1 ---
// --- Output 2: per-cycle max weight tracking (index 12 * 0.01, cycle index 15) ---

const data = msg.payload;

// Output 1
const out1 = (data[1] ?? 0) * 0.01;

// Output 2 (cycle max weight)
let lastCycle = context.get('lastCycle');
let maxWeight = context.get('maxWeight') || 0;

const weight = (data[12] ?? 0) * 0.01;
const cycle = data[15];

// Initialize lastCycle on first run
if (lastCycle === undefined || lastCycle === null) {
  lastCycle = cycle;
}

// Same cycle: update max and do not emit output 2 yet
if (cycle === lastCycle) {
  if (weight > maxWeight) maxWeight = weight;

  context.set('maxWeight', maxWeight);
  context.set('lastCycle', lastCycle);

  // 2 outputs: out1 always, out2 only when cycle changes
  return [ { payload: out1 }, null ];
}

// Cycle changed: emit previous cycle result and reset tracking
const out2 = {
  cycle: lastCycle,
  weight: maxWeight,
  timestamp: new Date().toISOString()
};

// Reset for new cycle
context.set('lastCycle', cycle);
context.set('maxWeight', weight);

// Return 2 outputs
return [ { payload: out1 }, { payload: out2 } ];

const timestamp = new Date().toISOString();
const weight = msg.payload.weight;

msg.topic = `INSERT INTO weights (timestamp, weight) VALUES ('${timestamp}', ${weight});`;
return msg;

const kgph = Number(msg.payload?.[0]?.projected_weight_per_hour) || 0;
msg.topic = 'projected_tph';
msg.payload = Math.round((kgph / 1000) * 1000) / 1000; // tons/h, 3 decimals
return msg;

const kg = Number(msg.payload?.[0]?.shift_weight) || 0;
msg.topic = 'tons_shift';
msg.payload = Math.round((kg / 1000) * 1000) / 1000; // tons, 3 decimals
return msg;

const kg = Number(msg.payload?.[0]?.total_weight) || 0;
msg.topic = 'grand_total';
msg.payload = Math.round((kg / 1000) * 1000) / 1000; // tons, 3 decimals
return msg;

// Generates SQL msgs:
// - projected: goes to ALL DBs
// - shift(reset): DB 1-3 uses flow.shiftStartISO_reset
// - shift(product): DB 4-7 uses flow.shiftStartISO_product

const now = Date.now();
const fallbackShift = new Date(now - 30 * 24 * 60 * 60 * 1000).toISOString();

function getISO(key) {
  const v = flow.get(key);
  return (typeof v === 'string' && v.length > 10) ? v : fallbackShift;
}

const cutoffReset = getISO('shiftStartISO_reset');     // DB 1-3
const cutoffProd  = getISO('shiftStartISO_product');   // DB 4-7

const msgs = [];

// 1) Projected weight per hour (kg/h)
msgs.push({
  queryType: 'projected',
  dbGroup: 'all',
  topic: `SELECT
            COALESCE((
              CASE
                WHEN EXISTS(
                  SELECT 1
                  FROM weights
                  WHERE timestamp >= strftime('%Y-%m-%dT%H:%M:%fZ','now','-1 minute')
                )
                THEN (
                  (SELECT COUNT(*) FROM weights WHERE timestamp >= strftime('%Y-%m-%dT%H:%M:%fZ','now','-5 minutes'))
                  * (SELECT weight FROM weights ORDER BY timestamp DESC LIMIT 1)
                  * 12
                )
                ELSE 0
              END
            ), 0) AS projected_weight_per_hour;`
});

// 2) Shift total for DB 1-3
msgs.push({
  queryType: 'shift',
  dbGroup: 'reset',
  topic: `SELECT COALESCE(SUM(weight),0) AS shift_weight
          FROM weights
          WHERE timestamp >= '${cutoffReset}';`
});

// 3) Shift total for DB 4-7
msgs.push({
  queryType: 'shift',
  dbGroup: 'product',
  topic: `SELECT COALESCE(SUM(weight),0) AS shift_weight
          FROM weights
          WHERE timestamp >= '${cutoffProd}';`
});

return [msgs];

return [{
  queryType: 'grand',
  dbGroup: 'all',
  topic: 'SELECT COALESCE(SUM(weight),0) AS total_weight FROM weights;'
}];

// Reads current cutoff for this endpoint (DB 1-3), queries prevTotal since cutoff.
// Then downstream we join results from the 3 DBs, set NEW cutoff, and reply once.

const startISO = flow.get('shiftStartISO_reset') || '1970-01-01T00:00:00Z';

msg.topic = `
  SELECT ROUND(COALESCE(SUM(weight),0)/1000.0, 3) AS prevTotal
  FROM weights
  WHERE datetime(timestamp) >= datetime('${startISO}')
`;

// mark endpoint so response builder knows which key to set
msg._endpoint = 'reset-shift';
return msg;

// Normalize sqlite rowset -> number
msg.payload = Number(msg.payload?.[0]?.prevTotal ?? 0);
return msg;

const arr = Array.isArray(msg.payload) ? msg.payload : [];
const prevTotal = arr.reduce((a, b) => a + Number(b || 0), 0);

const nowISO = new Date().toISOString();
flow.set('shiftStartISO_reset', nowISO);

msg.payload = {
  ok: true,
  endpoint: 'reset-shift',
  shiftStart: nowISO,
  prevTotal: Number(prevTotal.toFixed(3))
};
return msg;

// Reads current cutoff for this endpoint (DB 4-7), queries prevTotal since cutoff.
// Then downstream we join results from the 4 DBs, set NEW cutoff, and reply once.

const startISO = flow.get('shiftStartISO_product') || '1970-01-01T00:00:00Z';

msg.topic = `
  SELECT ROUND(COALESCE(SUM(weight),0)/1000.0, 3) AS prevTotal
  FROM weights
  WHERE datetime(timestamp) >= datetime('${startISO}')
`;

msg._endpoint = 'product-change';
return msg;

const arr = Array.isArray(msg.payload) ? msg.payload : [];
const prevTotal = arr.reduce((a, b) => a + Number(b || 0), 0);

const nowISO = new Date().toISOString();
flow.set('shiftStartISO_product', nowISO);

msg.payload = {
  ok: true,
  endpoint: 'product-change',
  shiftStart: nowISO,
  prevTotal: Number(prevTotal.toFixed(3))
};
return msg;

let data = msg.payload;

// Confirm required fields exist
if (!data || !data.device_id || !data.last_line) {
    node.warn("Missing device_id or last_line");
    return null;
}

let deviceId = data.device_id;
let line = data.last_line;

let match = line.match(/([+-]?\s*\d+)\s*kg/i);

if (!match) {
    node.warn("No weight found in line: " + line);
    return null;
}

let weight = parseInt(match[1].replace(/\s+/g, ""), 10);

msg.measurement = "weight";

msg.payload = [
    {
        value: weight
    },
    {
        device_id: deviceId
    }
];

return msg;

const out=[];
for(const s of ["silo1","silo2","silo3","silo4"]){
  const v=flow.get("val_"+s); if(v==null) continue;
  out.push({measurement:"silo_weight", payload:[{weight_kg:v, stable:true, status:"heartbeat"},{silo_id:s}]});
}
return [out];

